        }

        .btn-publish:hover:not(:disabled) {
          background-color: var(--accent-color);
          color: #333;
          transform: translateY(-1px);
        }

        .btn-draft {
          background-color: #f39c12;
          color: white;
          flex: 1;
          min-width: 150px;
          box-shadow: 0 3px 6px rgba(0, 0, 0, 0.1);
        }

