import { useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import { useAuth } from '../context/AuthContext';
import { getMyDrafts } from '../api/user';
import { queryKeys } from '../lib/queryKeys';
import Breadcrumbs from '../components/Breadcrumbs';
import PersonalSidebar from '../components/PersonalSidebar';

/**
 * CC98 风格我的草稿箱页面
 */
export default function MyDraftsPage() {
  const { user } = useAuth();
  const navigate = useNavigate();

  const { data: myDrafts = [], isLoading, error } = useQuery({
    queryKey: queryKeys.users.meDrafts(),
    queryFn: () => getMyDrafts(),
    enabled: !!user,
  });

  const formatTime = (timeStr: string) => {
    return timeStr.replace('T', ' ').split('.')[0] || timeStr;
  };

  if (isLoading) {
    return (
      <div style={{ textAlign: 'center', padding: '5rem 0' }}>
        <div className="spinner"></div>
        <p style={{ marginTop: '1.25rem', color: 'var(--text-muted)' }}>正在载入您的草稿箱...</p>
      </div>
    );
  }

  if (error) {
    const errorMessage = (error as any)?.response?.data?.message || '加载草稿失败';
    return (
      <div className="container" style={{ marginTop: '2rem' }}>
        <div className="cc98-editor-card" style={{ padding: '3rem 1.5rem', textAlign: 'center' }}>
          <i className="fa fa-exclamation-triangle" style={{ fontSize: '2.5rem', color: '#fb6165', marginBottom: '1rem' }}></i>
          <h2>获取草稿数据失败</h2>
          <p style={{ color: 'var(--text-muted)', margin: '1rem 0' }}>{errorMessage}</p>
          <button className="btn btn-primary" onClick={() => navigate('/dashboard')}>
            返回个人中心
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="cc98-my-drafts-page container" style={{ marginTop: '1.5rem', marginBottom: '3rem' }}>
      {/* 1. 面包屑 */}
      <Breadcrumbs 
        items={[
          { label: '首页', href: '/' },
          { label: '个人中心', href: '/dashboard' },
          { label: '我的草稿箱' }
        ]} 
      />

      {/* 2. 左右双栏布局 */}
      <div className="personal-center-layout" style={{ display: 'flex', gap: '1.5rem', marginTop: '1rem' }}>
        <PersonalSidebar />

        <div className="personal-center-content" style={{ flex: 1, minWidth: 0 }}>
          <div style={{ marginBottom: '1.25rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <h2 style={{ fontSize: '1.25rem', fontWeight: 'bold', margin: 0, color: 'var(--text-main)' }}>我的草稿</h2>
            <div className="summary-info">
              共 {myDrafts.length} 篇草稿
            </div>
          </div>

          {myDrafts.length === 0 ? (
            <div className="cc98-my-drafts-empty" style={{ padding: '3.5rem 1.5rem', textAlign: 'center', backgroundColor: 'var(--card-bg)', border: '1px dashed var(--border-color)', borderRadius: '4px', color: 'var(--text-muted)' }}>
              <i className="fa fa-sticky-note-o" style={{ fontSize: '2.5rem', opacity: 0.4, display: 'block', marginBottom: '0.8rem' }}></i>
              暂无草稿
            </div>
          ) : (
            <div className="cc98-drafts-grid">
              {myDrafts.map((draft) => (
                <div
                  key={draft.id}
                  className="card cc98-draft-card"
                  onClick={() => navigate(`/posts/new?draftId=${draft.id}`)}
                >
                  <div className="draft-card-header">
                    <span className="draft-tag">草稿</span>
                    <span className="draft-time">{formatTime(draft.createdAt)}</span>
                  </div>
                  <h3 className="draft-card-title">{draft.title || '(无标题)'}</h3>
                  <p className="draft-card-body">{draft.content || '(空内容)'}</p>
                  <div className="draft-card-footer">
                    <span>版块: {draft.categoryName || '未指定'}</span>
                    <span className="edit-action"><i className="fa fa-edit"></i> 继续编辑</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      <style>{`
        .summary-info {
          font-size: 0.9rem;
          color: var(--text-muted);
        }

        .cc98-my-drafts-empty {
          background-color: var(--card-bg);
          border: 1px dashed var(--border-color);
          border-radius: var(--cc98-radius);
          padding: 3.5rem 1.5rem;
          text-align: center;
          color: var(--text-muted);
          font-size: 0.92rem;
        }

        .cc98-drafts-grid {
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
          gap: 1.25rem;
        }

        .cc98-draft-card {
          background-color: var(--card-bg);
          border: 1px solid var(--border-color);
          border-top: 4px solid #f39c12;
          border-radius: var(--cc98-radius);
          padding: 1.25rem;
          cursor: pointer;
          display: flex;
          flex-direction: column;
          box-shadow: var(--cc98-shadow);
          transition: var(--cc98-transition);
        }

        .cc98-draft-card:hover {
          transform: translateY(-3px);
          border-color: #f39c12;
        }

        .draft-card-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 0.75rem;
        }

        .draft-tag {
          background-color: #f39c12;
          color: white;
          font-size: 0.72rem;
          font-weight: bold;
          padding: 0.1rem 0.4rem;
          border-radius: 3px;
        }

        .draft-time {
          font-size: 0.75rem;
          color: var(--text-muted);
        }

        .draft-card-title {
          font-size: 1rem;
          font-weight: bold;
          color: var(--text-main);
          margin: 0 0 0.5rem 0;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }

        .draft-card-body {
          font-size: 0.85rem;
          color: var(--text-muted);
          margin: 0 0 1rem 0;
          line-height: 1.5;
          display: -webkit-box;
          -webkit-line-clamp: 3;
          -webkit-box-orient: vertical;
          overflow: hidden;
          flex-grow: 1;
        }

        .draft-card-footer {
          display: flex;
          justify-content: space-between;
          font-size: 0.78rem;
          color: var(--text-muted);
          border-top: 1px dashed var(--border-color);
          padding-top: 0.75rem;
          margin-top: auto;
        }

        .edit-action {
          color: #f39c12;
          font-weight: bold;
        }
      `}</style>
    </div>
  );
}

