1	import { useNavigate } from 'react-router-dom';
2	import { useQuery } from '@tanstack/react-query';
3	import { useAuth } from '../context/AuthContext';
4	import { getNotifications, getUnreadCount } from '../api/notification';
5	import { getMyComments, getMyPosts, getMyDrafts } from '../api/user';
6	import { getMyBookmarks } from '../api/bookmark';
7	import { queryKeys } from '../lib/queryKeys';
8	import Breadcrumbs from '../components/Breadcrumbs';
9	
10	/**
11	 * CC98 风格用户 Dashboard 个人中心页面
12	 */
13	export default function DashboardPage() {
14	  const { user, logout } = useAuth();
15	  const navigate = useNavigate();
16	
17	  // 获取最近通知
18	  const { data: recentNotifications = [], isLoading: notificationsLoading } = useQuery({
19	    queryKey: queryKeys.notifications.list(0, 5),
20	    queryFn: () => getNotifications(0, 5),
21	    enabled: !!user,
22	  });
23	
24	  // 获取未读数
25	  const { data: unreadCount = 0 } = useQuery({
26	    queryKey: queryKeys.notifications.unreadCount(),
27	    queryFn: () => getUnreadCount(),
28	    enabled: !!user,
29	  });
30	
31	  // 获取我的帖子
32	  const {
33	    data: myPosts = [],
34	    isLoading: myPostsLoading,
35	    error: myPostsError,
36	  } = useQuery({
37	    queryKey: queryKeys.users.mePosts(),
38	    queryFn: () => getMyPosts(),
39	    enabled: !!user,
40	  });
41	
42	  // 获取我的评论
43	  const {
44	    data: myComments = [],
45	    isLoading: myCommentsLoading,
46	    error: myCommentsError,
47	  } = useQuery({
48	    queryKey: queryKeys.users.meComments(),
49	    queryFn: () => getMyComments(),
50	    enabled: !!user,
51	  });
52	
53	  // 获取我的草稿（仅最新一条）
54	  const { data: myDrafts = [] } = useQuery({
55	    queryKey: queryKeys.users.meDrafts(),
56	    queryFn: () => getMyDrafts(),
57	    enabled: !!user,
58	  });
59	
60	  // 获取我的收藏帖子
61	  const {
62	    data: myBookmarks = [],
63	    isLoading: myBookmarksLoading,
64	    error: myBookmarksError,
65	  } = useQuery({
66	    queryKey: ['users', 'me', 'bookmarks'],
67	    queryFn: () => getMyBookmarks(),
68	    enabled: !!user,
69	  });
70	
71	  const formatTime = (timeStr: string) => {
72	    return timeStr.replace('T', ' ').split('.')[0] || timeStr;
73	  };
74	
75	  return (
76	    <div className="cc98-dashboard-page container" style={{ marginTop: '1.5rem', marginBottom: '3rem' }}>
77	      {/* 1. 面包屑 */}
78	      <Breadcrumbs 
79	        items={[
80	          { label: '论坛首页', href: '/' },
81	          { label: '个人中心' }
82	        ]} 
83	      />
84	
85	      {/* 2. 欢迎卡片 */}
86	      <div className="cc98-welcome-banner">
87	        <div className="banner-details">
88	          <h1>
89	            欢迎回来，<span className="username-highlight">{user?.username}</span>！
90	          </h1>
91	          <p>这是您的个人控制面板。在这里您可以管理主题帖、追踪回帖通知和编辑草稿。</p>
92	        </div>
93	        <div className="banner-actions">
94	          <button onClick={logout} className="cc98-logout-btn">
95	            <i className="fa fa-sign-out"></i> 安全退出
96	          </button>
97	        </div>
98	      </div>
99	
100	      {/* 3. 快捷卡片网格 */}
101	      <div className="cc98-quick-actions-grid">
102	        <div className="cc98-quick-card" onClick={() => navigate('/posts/new')}>
103	          <div className="quick-icon"><i className="fa fa-pencil-square-o"></i></div>
104	          <div className="quick-title">发表新帖</div>
105	          <div className="quick-desc">发布讨论帖至各板块</div>
106	        </div>
107	
108	        <div className="cc98-quick-card" onClick={() => navigate('/notifications')}>
109	          <div className="quick-icon" style={{ position: 'relative' }}>
110	            <i className="fa fa-bell-o"></i>
111	            {unreadCount > 0 && (
112	              <span className="badge-danger-dot">
113	                {unreadCount > 99 ? '99+' : unreadCount}
114	              </span>
115	            )}
116	          </div>
117	          <div className="quick-title">消息通知</div>
118	          <div className="quick-desc">查看收到的回复和私信</div>
119	        </div>
120	
121	        <div className="cc98-quick-card" onClick={() => navigate(`/profile/${user?.username}`)}>
122	          <div className="quick-icon"><i className="fa fa-user-circle-o"></i></div>
123	          <div className="quick-title">我的资料</div>
124	          <div className="quick-desc">编辑个人信息与头像</div>
125	        </div>
126	
127	        <div className="cc98-quick-card" onClick={() => navigate('/dashboard/password')}>
128	          <div className="quick-icon"><i className="fa fa-lock"></i></div>
129	          <div className="quick-title">修改密码</div>
130	          <div className="quick-desc">更新登录密码</div>
131	        </div>
132	
133	        <div className="cc98-quick-card" onClick={() => navigate('/dashboard/bookmarks')}>
134	          <div className="quick-icon"><i className="fa fa-star-o"></i></div>
135	          <div className="quick-title">我的收藏</div>
136	          <div className="quick-desc">管理并浏览我收藏的帖子</div>
137	        </div>
138	
139	        {user?.role === 'ADMIN' && (
140	          <div className="cc98-quick-card admin-card" onClick={() => navigate('/admin')}>
141	            <div className="quick-icon"><i className="fa fa-cogs"></i></div>
142	            <div className="quick-title">管理后台</div>
143	            <div className="quick-desc">系统设置与板块管理</div>
144	          </div>
145	        )}
146	      </div>
147	
148	      {/* 4. 双栏主要内容 */}
149	      <div className="cc98-dashboard-grid">
150	        {/* 左栏：我的帖子 & 我的评论 */}
151	        <div className="cc98-dashboard-main-col">
152	          {/* 我的帖子 */}
153	          <div className="cc98-panel-classic col-b">
154	            <div className="cc98-panel-title">
155	              <i className="fa fa-file-text-o"></i> 我的主题帖
156	            </div>
157	            <div className="cc98-panel-body">
158	              {myPostsLoading ? (
159	                <div className="loading-state">载入中...</div>
160	              ) : myPostsError ? (
161	                <div className="error-state">获取主题帖列表失败</div>
162	              ) : myPosts.length === 0 ? (
163	                <div className="empty-state">您还没有发表过任何主题帖</div>
164	              ) : (
165	                <ul className="cc98-dashboard-list">
166	                  {myPosts.slice(0, 5).map((post) => (
167	                    <li key={post.id} onClick={() => navigate(`/posts/${post.id}`)}>
168	                      <div className="item-title">{post.title}</div>
169	                      <div className="item-meta">
170	                        <span>发表于 {formatTime(post.createdAt)}</span>
171	                        <span>·</span>
172	                        <span>{post.commentCount ?? 0} 条评论</span>
173	                      </div>
174	                    </li>
175	                  ))}
176	                </ul>
177	              )}
178	              <button className="cc98-panel-btn" onClick={() => navigate('/dashboard/posts')}>
179	                查看全部帖子
180	              </button>
181	            </div>
182	          </div>
183	
184	          {/* 我的收藏 */}
185	          <div className="cc98-panel-classic col-orange" style={{ borderTop: '6px solid var(--accent-color)' }}>
186	            <div className="cc98-panel-title">
187	              <i className="fa fa-star-o"></i> 我的收藏帖子
188	            </div>
189	            <div className="cc98-panel-body">
190	              {myBookmarksLoading ? (
191	                <div className="loading-state">载入中...</div>
192	              ) : myBookmarksError ? (
193	                <div className="error-state">获取收藏列表失败</div>
194	              ) : myBookmarks.length === 0 ? (
195	                <div className="empty-state">您还没有收藏过任何主题帖</div>
196	              ) : (
197	                <ul className="cc98-dashboard-list">
198	                  {myBookmarks.slice(0, 5).map((post) => (
199	                    <li key={post.id} onClick={() => navigate(`/posts/${post.id}`)}>
200	                      <div className="item-title">{post.title}</div>
201	                      <div className="item-meta">
202	                        <span>作者: {post.authorUsername}</span>
203	                        <span>·</span>
204	                        <span>{post.commentCount ?? 0} 条评论</span>
205	                      </div>
206	                    </li>
207	                  ))}
208	                </ul>
209	              )}
210	              <button className="cc98-panel-btn" onClick={() => navigate('/dashboard/bookmarks')}>
211	                查看全部收藏
212	              </button>
213	            </div>
214	          </div>
215	
216	          {/* 我的评论 */}
217	          <div className="cc98-panel-classic col-a">
218	            <div className="cc98-panel-title">
219	              <i className="fa fa-comments-o"></i> 我的回复评论
220	            </div>
221	            <div className="cc98-panel-body">
222	              {myCommentsLoading ? (
223	                <div className="loading-state">载入中...</div>
224	              ) : myCommentsError ? (
225	                <div className="error-state">获取回复列表失败</div>
226	              ) : myComments.length === 0 ? (
227	                <div className="empty-state">您还没有发表过任何回复</div>
228	              ) : (
229	                <ul className="cc98-dashboard-list">
230	                  {myComments.slice(0, 5).map((comment) => (
231	                    <li key={comment.id} onClick={() => navigate(`/posts/${comment.postId}`)}>
232	                      <div className="item-title comment-text">{comment.content}</div>
233	                      <div className="item-meta">
234	                        <span>回复于 {formatTime(comment.createdAt)}</span>
235	                        <span>·</span>
236	                        <span className="source-topic">来自：{comment.postTitle}</span>
237	                      </div>
238	                    </li>
239	                  ))}
240	                </ul>
241	              )}
242	              <button className="cc98-panel-btn" onClick={() => navigate('/dashboard/comments')}>
243	                查看所有评论
244	              </button>
245	            </div>
246	          </div>
247	        </div>
248	
249	        {/* 右栏：最新通知 & 草稿箱 */}
250	        <div className="cc98-dashboard-side-col">
251	          {/* 最新通知 */}
252	          <div className="cc98-panel-classic col-red">
253	            <div className="cc98-panel-title" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
254	              <span><i className="fa fa-bell-o"></i> 最新消息通知</span>
255	              {unreadCount > 0 && <span className="title-unread-badge">{unreadCount} 未读</span>}
256	            </div>
257	            <div className="cc98-panel-body">
258	              {notificationsLoading ? (
259	                <div className="loading-state">载入中...</div>
260	              ) : recentNotifications.length === 0 ? (
261	                <div className="empty-state">暂无新通知消息</div>
262	              ) : (
263	                <ul className="cc98-dashboard-list notif-list">
264	                  {recentNotifications.map((notif) => (
265	                    <li 
266	                      key={notif.id} 
267	                      className={notif.isRead ? '' : 'unread-item'}
268	                      onClick={() => notif.relatedId && navigate(`/posts/${notif.relatedId}`)}
269	                    >
270	                      <div className="notif-header">
271	                        <span className="notif-indicator">{notif.type === 'REPLY' ? '💬 回复' : '🔔 系统'}</span>
272	                        <span className="time">{formatTime(notif.createdAt)}</span>
273	                      </div>
274	                      <div className="item-title">{notif.title}</div>
275	                      <div className="item-desc">{notif.content}</div>
276	                    </li>
277	                  ))}
278	                </ul>
279	              )}
280	              <button className="cc98-panel-btn" onClick={() => navigate('/notifications')}>
281	                查看所有通知消息
282	              </button>
283	            </div>
284	          </div>
285	
286	          {/* 草稿 */}
287	          <div className="cc98-panel-classic col-orange">
288	            <div className="cc98-panel-title">
289	              <i className="fa fa-pencil-square-o"></i> 草稿箱
290	            </div>
291	            <div className="cc98-panel-body">
292	              {myDrafts.length === 0 ? (
293	                <div className="empty-state">草稿箱空空如也</div>
294	              ) : (
295	                <ul className="cc98-dashboard-list draft-list">
296	                  {myDrafts.slice(0, 2).map((draft) => (
297	                    <li key={draft.id} onClick={() => navigate(`/posts/new?draftId=${draft.id}`)}>
298	                      <div className="item-title">
299	                        <span className="draft-tag">草稿</span>
300	                        {draft.title || '(暂无标题)'}
301	                      </div>
302	                      <div className="item-meta">
303	                        <span>保存于 {formatTime(draft.createdAt)}</span>
304	                      </div>
305	                    </li>
306	                  ))}
307	                </ul>
308	              )}
309	              <button className="cc98-panel-btn" onClick={() => navigate('/dashboard/drafts')}>
310	                打开我的草稿箱
311	              </button>
312	            </div>
313	          </div>
314	        </div>
315	      </div>
316	
317	      <style>{`
318	        .cc98-welcome-banner {
