        @media (max-width: 992px) {
          .cc98-dashboard-grid {
            flex-direction: column;
          }
          .cc98-dashboard-side-col {
            width: 100%;
          }
        }

        /* Panels styling */
        .cc98-panel-classic {
          border: 1px solid var(--border-color);
