1	package com.cc91.forumservice.service;
2	
3	import com.cc91.forumservice.client.CreateNotificationRequest;
4	import com.cc91.forumservice.client.NotificationServiceClient;
5	import com.cc91.forumservice.client.UserInfoDTO;
6	import com.cc91.forumservice.client.UserServiceClient;
7	import com.cc91.forumservice.dto.CommentResponse;
8	import com.cc91.forumservice.dto.CreateCommentRequest;
9	import com.cc91.forumservice.dto.UserCommentResponse;
10	import com.cc91.forumservice.entity.Comment;
11	import com.cc91.forumservice.entity.Post;
12	import com.cc91.forumservice.exception.ResourceNotFoundException;
13	import com.cc91.forumservice.util.HtmlSanitizer;
14	import com.cc91.forumservice.exception.UnauthorizedException;
15	import com.cc91.forumservice.repository.CommentRepository;
16	import com.cc91.forumservice.repository.PostRepository;
17	import org.slf4j.Logger;
18	import org.slf4j.LoggerFactory;
19	import org.springframework.stereotype.Service;
20	import org.springframework.transaction.annotation.Transactional;
21	
22	import java.util.*;
23	import java.util.ArrayList;
24	import java.util.stream.Collectors;
25	
26	/**
27	 * 评论服务
28	 */
29	@Service
30	public class CommentService {
31	
32	    private static final Logger logger = LoggerFactory.getLogger(CommentService.class);
33	
34	    private final CommentRepository commentRepository;
35	    private final PostRepository postRepository;
36	    private final UserServiceClient userServiceClient;
37	    private final NotificationServiceClient notificationServiceClient;
38	
39	    public CommentService(CommentRepository commentRepository,
40	                         PostRepository postRepository,
41	                         UserServiceClient userServiceClient,
42	                         NotificationServiceClient notificationServiceClient) {
43	        this.commentRepository = commentRepository;
44	        this.postRepository = postRepository;
45	        this.userServiceClient = userServiceClient;
46	        this.notificationServiceClient = notificationServiceClient;
47	    }
48	
49	    /**
50	     * 创建评论
51	     */
52	    @Transactional
53	    public CommentResponse createComment(String username, Long postId, CreateCommentRequest request) {
54	        UserInfoDTO user = userServiceClient.getUserByUsername(username);
55	        if (user == null) {
56	            throw new ResourceNotFoundException("用户不存在");
57	        }
58	
59	        Post post = postRepository.findById(postId)
60	                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));
61	
62	        Comment comment = new Comment(postId, user.getId(), HtmlSanitizer.sanitizeContent(request.getContent()), null);
63	        comment = commentRepository.save(comment);
64	
65	        // 如果评论的不是自己的帖子，通知帖子作者
66	        if (!post.getAuthorId().equals(user.getId())) {
67	            try {
68	                UserInfoDTO postAuthor = userServiceClient.getUserById(post.getAuthorId());
69	                if (postAuthor != null) {
70	                    notificationServiceClient.createNotification(
71	                            new CreateNotificationRequest(
72	                                    post.getAuthorId(),
73	                                    "REPLY",
74	                                    "新评论通知",
75	                                    user.getUsername() + " 评论了你的帖子: " + post.getTitle(),
76	                                    comment.getId()
77	                            )
78	                    );
79	                }
80	            } catch (Exception e) {
81	                logger.warn("Failed to send notification for comment on post {}", postId, e);
82	            }
83	        }
84	
85	        logger.info("评论创建成功: id={}, postId={}, author={}", comment.getId(), postId, username);
86	
87	        return toCommentResponse(comment, user.getUsername(), user.getAvatarUrl());
88	    }
89	
90	    /**
91	     * 回复评论
92	     */
93	    @Transactional
94	    public CommentResponse replyToComment(String username, Long commentId, CreateCommentRequest request) {
95	        UserInfoDTO user = userServiceClient.getUserByUsername(username);
96	        if (user == null) {
97	            throw new ResourceNotFoundException("用户不存在");
98	        }
99	
100	        Comment parentComment = commentRepository.findById(commentId)
101	                .orElseThrow(() -> new ResourceNotFoundException("评论不存在"));
102	
103	        Comment reply = new Comment(parentComment.getPostId(), user.getId(),
104	                                    HtmlSanitizer.sanitizeContent(request.getContent()), commentId);
105	        reply = commentRepository.save(reply);
106	
107	        // 通知被回复的评论作者（如果不是自己回复自己）
108	        if (!parentComment.getAuthorId().equals(user.getId())) {
109	            try {
110	                Post post = postRepository.findById(parentComment.getPostId()).orElse(null);
111	                String postTitle = post != null ? post.getTitle() : "未知帖子";
112	                notificationServiceClient.createNotification(
113	                        new CreateNotificationRequest(
114	                                parentComment.getAuthorId(),
115	                                "REPLY",
116	                                "新回复通知",
117	                                user.getUsername() + " 回复了你在「" + postTitle + "」中的评论",
118	                                reply.getId()
119	                        )
120	                );
121	            } catch (Exception e) {
122	                logger.warn("Failed to send notification for reply to comment {}", commentId, e);
123	            }
124	        }
125	
126	        logger.info("回复评论成功: id={}, parentId={}, author={}", reply.getId(), commentId, username);
127	
128	        return toCommentResponse(reply, user.getUsername(), user.getAvatarUrl());
129	    }
130	
131	    /**
132	     * 编辑评论
133	     */
134	    @Transactional
135	    public CommentResponse updateComment(String username, Long commentId, String content) {
136	        UserInfoDTO user = userServiceClient.getUserByUsername(username);
137	        if (user == null) {
138	            throw new ResourceNotFoundException("用户不存在");
139	        }
140	
141	        Comment comment = commentRepository.findById(commentId)
142	                .orElseThrow(() -> new ResourceNotFoundException("评论不存在"));
143	
144	        if (!comment.getAuthorId().equals(user.getId())) {
145	            throw new UnauthorizedException("无权限编辑此评论");
146	        }
147	
148	        comment.setContent(HtmlSanitizer.sanitizeContent(content));
149	        comment = commentRepository.save(comment);
150	
151	        logger.info("评论更新成功: id={}, author={}", commentId, username);
152	
153	        return toCommentResponse(comment, user.getUsername(), user.getAvatarUrl());
154	    }
155	
156	    /**
157	     * 删除评论（软删除）
158	     */
159	    @Transactional
160	    public void deleteComment(String username, Long commentId) {
161	        UserInfoDTO user = userServiceClient.getUserByUsername(username);
162	        if (user == null) {
163	            throw new ResourceNotFoundException("用户不存在");
164	        }
165	
166	        Comment comment = commentRepository.findById(commentId)
167	                .orElseThrow(() -> new ResourceNotFoundException("评论不存在"));
168	
169	        if (!comment.getAuthorId().equals(user.getId())) {
170	            throw new UnauthorizedException("无权限删除此评论");
171	        }
172	
173	        comment.setStatus("DELETED");
174	        commentRepository.save(comment);
175	
176	        List<Comment> replies = commentRepository.findByParentIdOrderByCreatedAtAsc(commentId);
177	        for (Comment reply : replies) {
178	            reply.setStatus("DELETED");
179	        }
180	        commentRepository.saveAll(replies);
181	
182	        logger.info("评论删除成功: id={}, 关联子评论数={}, author={}", commentId, replies.size(), username);
183	    }
184	
185	    /**
186	     * 获取帖子的所有评论（树形结构）
187	     */
188	    @Transactional(readOnly = true)
189	    public List<CommentResponse> getCommentsByPostId(Long postId) {
190	        Post post = postRepository.findById(postId)
191	                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));
192	
193	        List<Comment> comments = commentRepository.findByPostIdAndStatusOrderByCreatedAtAsc(postId, "PUBLISHED");
194	
195	        Set<Long> authorIds = comments.stream()
196	                .map(Comment::getAuthorId)
197	                .collect(Collectors.toSet());
198	
199	        Map<Long, UserInfoDTO> userMap = batchResolveUsers(authorIds);
200	
201	        return buildCommentTree(comments, userMap);
202	    }
203	
204	    /**
205	     * 获取当前用户的评论列表（用于 Dashboard "我的评论"）
206	     */
207	    @Transactional(readOnly = true)
208	    public List<UserCommentResponse> getMyComments(String username) {
