3	import jakarta.persistence.*;
4	import java.time.LocalDateTime;
5	import java.util.ArrayList;
6	import java.util.List;
7	
8	/**
9	 * 评论实体类
10	 */
11	@Entity
12	@Table(name = "comments", indexes = {
13	    @Index(name = "idx_comments_post_id", columnList = "post_id"),
14	    @Index(name = "idx_comments_author_id", columnList = "author_id"),
15	    @Index(name = "idx_comments_parent_id", columnList = "parent_id"),
16	    @Index(name = "idx_comments_created_at", columnList = "created_at"),
17	    @Index(name = "idx_comments_status", columnList = "status")
18	})
19	public class Comment {
20	
21	    @Id
22	    @GeneratedValue(strategy = GenerationType.IDENTITY)
23	    private Long id;
24	
25	    @Column(name = "post_id", nullable = false)
26	    private Long postId;
27	
28	    @ManyToOne(fetch = FetchType.LAZY)
29	    @JoinColumn(name = "post_id", insertable = false, updatable = false)
30	    private Post post;
31	
32	    @Column(name = "author_id", nullable = false)
33	    private Long authorId;
34	
35	    @Column(nullable = false, columnDefinition = "TEXT")
36	    private String content;
37	
38	    @Column(name = "parent_id")
39	    private Long parentId;
40	
41	    @ManyToOne(fetch = FetchType.LAZY)
42	    @JoinColumn(name = "parent_id", insertable = false, updatable = false)
43	    private Comment parent;
44	
45	    @OneToMany(mappedBy = "parent", cascade = CascadeType.ALL)
46	    private List<Comment> replies = new ArrayList<>();
47	
48	    @Column(name = "created_at", nullable = false, updatable = false)
49	    private LocalDateTime createdAt;
50	
51	    @Column(name = "updated_at")
52	    private LocalDateTime updatedAt;
53	
54	    @Column(length = 20, nullable = false)
55	    private String status = "PUBLISHED";
56	
57	    @PrePersist
58	    protected void onCreate() {
59	        if (createdAt == null) {
60	            createdAt = LocalDateTime.now();
61	        }
62	        if (updatedAt == null) {
63	            updatedAt = LocalDateTime.now();
64	        }
65	    }
66	
67	    @PreUpdate
68	    protected void onUpdate() {
69	        updatedAt = LocalDateTime.now();
70	    }
71	
72	    public Comment() {}
73	
74	    public Comment(Long postId, Long authorId, String content, Long parentId) {
75	        this.postId = postId;
76	        this.authorId = authorId;
77	        this.content = content;
78	        this.parentId = parentId;
79	    }
80	
81	    public Long getId() { return id; }
82	    public void setId(Long id) { this.id = id; }
83	
84	    public Long getPostId() { return postId; }
85	    public void setPostId(Long postId) { this.postId = postId; }
86	
87	    public Post getPost() { return post; }
88	    public void setPost(Post post) { this.post = post; }
89	
90	    public Long getAuthorId() { return authorId; }
91	    public void setAuthorId(Long authorId) { this.authorId = authorId; }
92	
93	    public String getContent() { return content; }
94	    public void setContent(String content) { this.content = content; }
95	
96	    public Long getParentId() { return parentId; }
97	    public void setParentId(Long parentId) { this.parentId = parentId; }
